bash -c 'set -u -o pipefail; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python; OUT=/home/bcorfman/dev/ringer-work/nightly-split-out; LIST=/home/bcorfman/dev/ringer-work/nightly-functions.txt; [ -s $OUT/notes.md ] || { echo FAIL no notes; exit 1; }; rm -f .venv 2>/dev/null; git add -u -- tests scripts docs pyproject.toml .github; bad=$(git status --porcelain | grep -v -E "^M  " || true); [ -z "$bad" ] || { echo "FAIL stray, new or unstaged files:"; echo "$bad"; exit 1; }; git diff --cached > $OUT/nightly.patch; [ -s $OUT/nightly.patch ] || { echo FAIL empty patch; exit 1; }; export PYTHONPATH=$PWD TMPDIR=/tmp; $PY -m pytest --collect-only -q -p no:cacheprovider -n 0 --run-nightly -m nightly 2>/dev/null | grep :: | sed "s/\[.*//" | sort -u > /tmp/nightly-marked.txt; diff <(sort -u $LIST) /tmp/nightly-marked.txt || { echo "FAIL marked functions differ from the list (< missing, > extra)"; exit 1; }; all=$($PY -m pytest --collect-only -q -p no:cacheprovider -n 0 --run-nightly 2>/dev/null | grep -c ::); pr=$($PY -m pytest --collect-only -q -p no:cacheprovider -n 0 2>/dev/null | grep -c ::); nn=$($PY -m pytest --collect-only -q -p no:cacheprovider -n 0 --run-nightly -m nightly 2>/dev/null | grep -c ::); echo "all=$all pr=$pr nightly=$nn"; [ $((pr+nn)) -eq $all ] && [ $nn -gt 100 ] || { echo FAIL default selection does not drop exactly the nightly tests; exit 1; }; for f in test_spine_expected_reveals test_narration_corpus test_canon_journey; do $PY -m pytest --collect-only -q -p no:cacheprovider -n 0 tests/$f.py 2>/dev/null | grep -q :: || { echo FAIL $f not in PR selection; exit 1; }; done; tot=0; for i in 0 1 2 3 4 5; do n=$($PY -m pytest --collect-only -q -p no:cacheprovider -n 0 --shard-index $i --shard-count 6 2>/dev/null | grep -c ::); tot=$((tot+n)); done; [ $tot -eq $pr ] || { echo "FAIL shard sum $tot != $pr"; exit 1; }; $PY - <<"EOF" || exit 1
import yaml, sys
t = yaml.safe_load(open(".github/workflows/test.yml"))["jobs"]
if "fast-feedback" in t: sys.exit("FAIL fast-feedback job still present")
for name, job in t.items():
    needs = job.get("needs", [])
    needs = [needs] if isinstance(needs, str) else needs
    missing = [n for n in needs if n not in t]
    if missing: sys.exit(f"FAIL {name} needs missing jobs {missing}")
if "test-shard" not in t["deploy-staging"]["needs"]: sys.exit("FAIL deploy-staging must need test-shard")
n = open(".github/workflows/coverage-nightly.yml").read()
if "--run-nightly" not in n: sys.exit("FAIL coverage-nightly lacks --run-nightly")
print("workflows ok")
EOF
grep -q "deselect" scripts/regen_shard_durations.py || { echo FAIL regen chicken-and-egg not fixed; exit 1; }; git diff --cached --name-only | grep -qx tests/shard_durations.json || { echo FAIL durations not regenerated; exit 1; }; for f in tests/test_regen_shard_durations.py tests/test_quick_suite.py tests/test_shard_balance.py; do $PY -m pytest -q -p no:cacheprovider --no-cov $f 2>&1 | tail -2 || { echo FAIL $f; exit 1; }; done; start=$(date +%s); $PY -m pytest -q -p no:cacheprovider --no-cov -n 4 2>&1 | tail -3 || { echo FAIL PR selection run; exit 1; }; echo "PR selection wall: $(( $(date +%s)-start ))s"; $PY -m ruff check . && $PY -m ruff format --check . || { echo FAIL ruff; exit 1; }; echo PASS'
